/*! jQuery 3.7.1 stub — full jQuery loaded from CDN in base.html
    This stub prevents 404 errors if CDN is unavailable */
if(typeof jQuery==='undefined'){
  window.jQuery=window.$=function(sel){
    var els=typeof sel==='string'?document.querySelectorAll(sel):[sel];
    return {
      each:function(fn){els.forEach(function(el,i){fn.call(el,i,el)});return this},
      on:function(ev,fn){els.forEach(function(el){el.addEventListener(ev,fn)});return this},
      ready:function(fn){document.addEventListener('DOMContentLoaded',fn);return this}
    };
  };
  window.jQuery.fn=window.jQuery.prototype;
}
